def pancake_sort(arr):
    a = arr[:]
    flips = []

    def reverse(k):
        lo, hi = 0, k - 1
        while lo < hi:
            a[lo], a[hi] = a[hi], a[lo]
            lo += 1
            hi -= 1

    for size in range(len(a), 1, -1):
        max_idx = 0
        for i in range(size):
            if a[i] > a[max_idx]:
                max_idx = i
        if max_idx == size - 1:
            continue
        for i in range(1, size + 1):
            reverse(i)
            flips.append(i)

    return flips


if __name__ == "__main__":
    print(pancake_sort([3, 2, 4, 1]))
    print(pancake_sort([1, 2, 3]))

