import java.util.*;

public class Main {
    static int[] a;

    static void reverse(int k) {
        int lo = 0, hi = k - 1;
        while (lo < hi) {
            int tmp = a[lo]; a[lo] = a[hi]; a[hi] = tmp;
            lo++; hi--;
        }
    }

    static List<Integer> pancakeSort(int[] arr) {
        a = arr.clone();
        List<Integer> flips = new ArrayList<>();

        for (int size = a.length; size > 1; size--) {
            int maxIdx = 0;
            for (int i = 0; i < size; i++) {
                if (a[i] > a[maxIdx]) maxIdx = i;
            }
            if (maxIdx == size - 1) continue;
            for (int i = 1; i <= size; i++) {
                reverse(i);
                flips.add(i);
            }
        }
        return flips;
    }

    public static void main(String[] args) {
        System.out.println(pancakeSort(new int[]{3, 2, 4, 1}));
        System.out.println(pancakeSort(new int[]{1, 2, 3}));
    }
}

